    }

    int ans = 0;

    /* Enumerate subsets of rows to be included in the rectangle.
       For a chosen non-empty subset R, we can choose row flips so that
       all rows in R become equal on each column iff their original bits
       on that column are either all 0 or all 1 after considering row flips.
       Equivalently, fix one row in R as reference; then a column is usable
       iff all rows in R have the same original color on that column.
       Then by flipping that column if needed, all cells in R on that column
       can be made black. Area = |R| * (#usable columns). */
    int totalMasks = 1 << H;
    for (int mask = 1; mask < totalMasks; mask++) {
        int first = 0;
        while (((mask >> first) & 1) == 0) first++;

        int rows = 0;
        for (int i = 0; i < H; i++) if ((mask >> i) & 1) rows++;

        int cols = 0;
        for (int j = 0; j < W; j++) {
            char c = S[(size_t)first * (W + 1) + j];
            int ok = 1;
            for (int i = first + 1; i < H; i++) {
