                    if (S[(size_t)i * (W + 1) + j] != c) {
                        ok = 0;
                        break;
                    }
                }
            }
            if (ok) cols++;
        }

        int area = rows * cols;
        if (area > ans) ans = area;
    }

    printf("%d\n", ans);
    free(S);
    return 0;
