int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; ++i) cin >> S[i];

    // Let row flips be r[i], column flips be c[j].
    // A cell (i,j) becomes black iff S[i][j] xor r[i] xor c[j] = 1.
    //
    // For a chosen set of rows R and columns C forming the rectangle,
    // we need all cells in R x C to be black.
    //
    // Fix the row flips for rows in R. Then for each column j, all rows in R
    // must agree on the value of c[j]:
    //   c[j] = 1 xor S[i][j] xor r[i]   for every i in R
    // Hence for any two rows a,b in R:
    //   S[a][j] xor r[a] = S[b][j] xor r[b]
    // meaning the row patterns must be either identical or bitwise complements.
    //
    // Therefore, for any subset of rows R, we can choose row flips so that
    // rows in R become identical iff every row in R is either equal to some
    // pattern P or its complement. Then every column where the unified bit is 1
    // can be included in the rectangle.
    //
    // So for each subset of rows, count columns where all bits on these rows
    // are equal (all 0 or all 1). Those columns can be made black simultaneously.
    // Area = (#rows in subset) * (#such columns).

    long long ans = 0;

    // Enumerate subsets of rows. This is intended for H <= about 20.
    // If W < H, transpose to make enumeration smaller.
    if (H > W) {
        vector<string> T(W, string(H, '.'));
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                T[j][i] = S[i][j];
            }
        }
        swap(H, W);
        S = move(T);
    }

    int totalMasks = 1 << H;
    for (int mask = 1; mask < totalMasks; ++mask) {
        int rows = __builtin_popcount((unsigned)mask);
        int goodCols = 0;

        for (int j = 0; j < W; ++j) {
            int first = -1;
            bool ok = true;
            for (int i = 0; i < H; ++i) {
                if (!(mask >> i & 1)) continue;
                int bit = (S[i][j] == '#') ? 1 : 0;
                if (first == -1) first = bit;
                else if (bit != first) {
                    ok = false;
                    break;
                }
            }
            if (ok) goodCols++;
        }

        ans = max(ans, 1LL * rows * goodCols);
    }

    cout << ans << '\n';
    return 0;
}

