public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] s = new char[H][];
        for (int i = 0; i < H; i++) s[i] = fs.next().toCharArray();

        // We choose a subset of rows to be inside the rectangle.
        // For those rows, after optional row flips, in each chosen column
        // all cells must become equal (then a column flip can make them all black).
        //
        // For a fixed row subset R:
        // A column can be used iff all values in that column on rows in R are identical.
        // Then area = |R| * (#usable columns).
        //
        // Enumerate all subsets of the smaller dimension.
        long ans = 0;

        if (H <= W) {
            int[][] a = new int[H][W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) a[i][j] = (s[i][j] == '#') ? 1 : 0;
            }

            int total = 1 << H;
            for (int mask = 1; mask < total; mask++) {
                int rows = Integer.bitCount(mask);
                int usable = 0;
                for (int col = 0; col < W; col++) {
                    int first = -1;
                    boolean ok = true;
                    for (int r = 0; r < H; r++) {
                        if (((mask >> r) & 1) == 0) continue;
                        if (first == -1) first = a[r][col];
                        else if (a[r][col] != first) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) usable++;
                }
                ans = Math.max(ans, (long) rows * usable);
            }
        } else {
            // Symmetric: choose subset of columns.
            int[][] a = new int[H][W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) a[i][j] = (s[i][j] == '#') ? 1 : 0;
            }

            int total = 1 << W;
            for (int mask = 1; mask < total; mask++) {
                int cols = Integer.bitCount(mask);
                int usable = 0;
                for (int row = 0; row < H; row++) {
                    int first = -1;
                    boolean ok = true;
                    for (int c = 0; c < W; c++) {
                        if (((mask >> c) & 1) == 0) continue;
                        if (first == -1) first = a[row][c];
                        else if (a[row][c] != first) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) usable++;
                }
                ans = Math.max(ans, (long) cols * usable);
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

