    W = int(input_data[1])
    grid = []
    for i in range(H):
        row = [1 if c == '#' else 0 for c in input_data[2+i]]
        grid.append(row)

    ans = 0

    for r1 in range(H):
        col_min = grid[r1][:]
        col_max = grid[r1][:]
        for r2 in range(r1, H):
            if r2 > r1:
                for j in range(W):
                    col_min[j] = min(col_min[j], grid[r2][j])
                    col_max[j] = max(col_max[j], grid[r2][j])
            # valid columns: col_min[j] == col_max[j]
            height = r2 - r1 + 1
            # find longest contiguous run of valid columns
            cur = 0
            for j in range(W):
                if col_min[j] == col_max[j]:
                    cur += 1
                    ans = max(ans, height * cur)
                else:
                    cur = 0

    print(ans)

