    input = sys.stdin.readline
    H, W = map(int, input().split())
    S = [input().strip() for _ in range(H)]

    # Convert each row to a bitmask: 1 for black('#'), 0 for white('.')
    rows = []
    for s in S:
        mask = 0
        for j, ch in enumerate(s):
            if ch == '#':
                mask |= 1 << j
        rows.append(mask)

    ans = 0

    # Enumerate the smaller dimension's subsets.
    # If H <= W, enumerate row subsets.
    # For a chosen set of rows R, after suitable row flips, a column can be made
    # all black on R iff the bits on R are either all 0 or all 1 in that column.
    # Then area = |R| * (#such columns).
    if H <= W:
        for rmask in range(1, 1 << H):
            cnt_rows = rmask.bit_count()
            same_cols = 0
            for j in range(W):
                first = None
                ok = True
                for i in range(H):
                    if (rmask >> i) & 1:
                        bit = (rows[i] >> j) & 1
                        if first is None:
                            first = bit
                        elif first != bit:
                            ok = False
                            break
                if ok:
                    same_cols += 1
            area = cnt_rows * same_cols
            if area > ans:
                ans = area
    else:
        # Enumerate column subsets symmetrically.
        # For a chosen set of columns C, after suitable column flips, a row can be
        # made all black on C iff the bits on C are either all 0 or all 1 in that row.
        for cmask in range(1, 1 << W):
            cnt_cols = cmask.bit_count()
            same_rows = 0
            for i in range(H):
                masked = rows[i] & cmask
                if masked == 0 or masked == cmask:
                    same_rows += 1
            area = cnt_cols * same_rows
            if area > ans:
                ans = area

    print(ans)

